examples.code:
import { defineCollection } from 'astro:content';
import { glob } from 'astro/loaders';
import { z } from 'astro/zod';
const blog=defineCollection({loader:glob({pattern:'**/*.md',base:'./src/content/blog'}),schema:z.object({title:z.string(),draft:z.boolean().default(false)})});
export const collections={blog};

---
import { getCollection } from 'astro:content';
const posts=await getCollection('blog');
---
<ul>{posts.map(post=><li>{post.data.title}</li>)}</ul>

---
import { getEntry, render } from 'astro:content';
const post=await getEntry('blog','primer-post');
const {Content}=await render(post);
---
<h1>{post.data.title}</h1><Content />

import { defineCollection } from 'astro:content';
import { file } from 'astro/loaders';
import { z } from 'astro/zod';
const productos=defineCollection({loader:file('src/data/productos.json'),schema:z.object({nombre:z.string(),precio:z.number()})});
export const collections={productos};

