---
let posts=[]; let error='';
try { const res=await fetch('https://api.example.com/posts'); if(!res.ok) throw new Error(`HTTP ${res.status}`); posts=await res.json(); }
catch(e){error=e instanceof Error?e.message:'Error'}
---
{error?<p role='alert'>{error}</p>:<p>{posts.length} posts</p>}

---
const [a,b]=await Promise.all([fetch('/api/posts'),fetch('/api/users')]);
if(!a.ok||!b.ok) throw new Error('Falló solicitud');
const [posts,users]=await Promise.all([a.json(),b.json()]);
---
<p>{posts.length} posts · {users.length} usuarios</p>

